alue="review"><input type="hidden" name="target_id" value="{{ $review->id }}"><input name="reason" placeholder="Reden van melding" required minlength="5"><button class="small-button">Verstuur</button></form></details></div> @endauth </article> @empty <div class="empty-state"><x-icon name="cup" size="36"/><h3>Nog een onbeschreven kop.</h3><p>Deel als eerste wat jij proeft.</p></div> @endforelse </div></section></div></x-layout>